<script>
window.dataLayer = window.dataLayer || [];
function gtag(){dataLayer.push(arguments);}
gtag('js', new Date());
gtag('config', 'G-YOUR_ID_HERE');
</script>


<!-- Fastly Bot Management Challenge Script -->
